def has_execution_lane_separation(response_text):
    for clause in _iter_clauses(response_text):
        if not (_clause_has_endpoint_lane(clause) and _clause_has_local_lane(clause)):
            continue
        positive_separation = bool(_find_contextual_term_hits(clause, ['separate', 'different lane', 'distinct lane'], skip_negated=True, skip_quoted=True))
        explicit_no_mix = bool(_find_contextual_term_hits(clause, ['do not mix', "don't mix", 'dont mix', 'must not mix', 'should not mix'], skip_negated=True, skip_quoted=True))
        if positive_separation or explicit_no_mix:
            return True
    return False

AMBIGUOUS_LIST_SECTION_HEADERS = {'retrieve', 'interpret', 'cleanup'}

def _final_section_header_for_line(line):
    normalized = _normalized_header_line(line)
    is_list_prefixed = _line_is_list_prefixed(line)
    if normalized in FINAL_SECTION_HEADERS:
        if is_list_prefixed and normalized in AMBIGUOUS_LIST_SECTION_HEADERS:
            return None
        return normalized
    for header in FINAL_SECTION_HEADERS:
        if is_list_prefixed and header in AMBIGUOUS_LIST_SECTION_HEADERS:
            continue
        if re.match(rf'^{re.escape(header)}\s*[:\-–—]\s*.+$', normalized):
            return header
    return None

def duplicate_final_sections(response_text):
    counts = {header: 0 for header in FINAL_SECTION_HEADERS}
    for line in str(response_text).splitlines():
        header = _final_section_header_for_line(line)
        if header is not None:
            counts[header] += 1
    return [header for header, count in counts.items() if count > 1]

def _row_errors(body, rows, lane):
    errors = []
    expected = [row for row in rows if _classification(row) == lane]
    required_fields = [
        ('Name(s)', 'User'),
        ('Location', 'Location'),
        ('Computer Name', 'Computer Name'),
        ('User Information', 'User Information'),
        ('USB Device', 'USB Device'),
        ('Serial Number', 'Serial Number'),
        ('Network Connection', 'Network connection'),
    ]
    for row in expected:
        ticket = _ticket(row)
        ticket_matches = list(re.finditer(rf'(?m)^{re.escape(ticket)}\\s*$', body))
        if len(ticket_matches) != 1:
            errors.append(f'{lane} body must contain ticket exactly once: {ticket}')
        expected_date = _expected_date_line(row)
        if expected_date not in body:
            errors.append(f'{lane} body missing source date/time: {expected_date}')
        for label, field in required_fields:
            value = _value(row, field)
            if not value:
                continue
            expected_line = f'{label}: {value}'
            if label == 'USB Device':
                found = expected_line.casefold() in body.casefold()
            else:
                found = expected_line in body
            if not found:
                errors.append(f'{lane} body missing source value {label}: {value}')
    return errors

def _row_errors(body, rows, lane):
    errors = []
    expected = [row for row in rows if _classification(row) == lane]
    ticket_matches = list(re.finditer(r'(?mi)^((?:INCN|INCS)\\S*)\\s*$', body))
    blocks = {}
    previous_end = 0
    for match in ticket_matches:
        ticket = match.group(1)
        blocks.setdefault(ticket, body[previous_end:match.end()])
        previous_end = match.end()

    for row in expected:
        ticket = _ticket(row)
        block = blocks.get(ticket, '')
        for label, field in required_fields:
            value = _value(row, field)
            if not value:
                continue
            expected_line = f'{label}: {value}'
            found = expected_line.casefold() in block.casefold() if label == 'USB Device' else expected_line in block
            if not found:
                errors.append(f'{lane} body missing source value {label} for ticket {ticket}: {value}')
    return errors
